// -----------------------------------------------------------------------------
// TLS to the hub. Its certificate is generated by the hub itself (the PDF
// says to skip its verification): it is pinned instead. Every connection is a
// bare TLS handshake first; the SHA-256 fingerprint of the certificate seen
// is compared with the pin BEFORE anything is written or read, so the token
// never reaches another server. Without a pin, nothing is sent: the pin comes
// from the user (typed in the configuration, or learnt on a click of "Test
// the connection", src/app.js). Pattern of gladys-jung-home (approved).
// -----------------------------------------------------------------------------

import { isIP } from 'node:net';
import tls from 'node:tls';
import { TIMINGS } from '../constants.js';
import { NeoHubError, networkError } from './errors.js';

const FINGERPRINT = /^([0-9A-F]{2}:){31}[0-9A-F]{2}$/;

const options = (host, port) => ({
  host,
  port,
  servername: isIP(host) ? undefined : host,
  // Self-signed: the CA check cannot pass; the pin replaces it (checked below, before any byte).
  rejectUnauthorized: false,
});

/** A TLS socket whose certificate is the pinned one; nothing written nor read before the check. */
export function connectPinned({
  host,
  port,
  pin,
  timeout = TIMINGS.connectTimeout,
  timers,
  onSocket,
}) {
  const t = timers ?? globalThis;
  return new Promise((resolve, reject) => {
    if (!pin) {
      reject(new NeoHubError('nopin', 'certificate not pinned'));
      return;
    }
    let done = false;
    const socket = tls.connect(options(host, port));
    // The caller may destroy it while the handshake runs (a standby cuts a stuck opening).
    onSocket?.(socket);
    socket.once('close', () => finish(new NeoHubError('closed', 'connection closed')));
    const finish = (err) => {
      if (done) return;
      done = true;
      t.clearTimeout(timer);
      socket.removeListener('secureConnect', onSecure);
      if (err) {
        socket.destroy();
        reject(err);
      } else {
        resolve(socket);
      }
    };
    const onSecure = () => {
      const seen = socket.getPeerCertificate()?.fingerprint256;
      if (seen !== pin) {
        finish(
          new NeoHubError('pin', 'the certificate of the hub changed', {
            fingerprint: FINGERPRINT.test(seen ?? '') ? seen : undefined,
          }),
        );
        return;
      }
      finish();
    };
    const timer = t.setTimeout(
      () => finish(new NeoHubError('timeout', 'no TLS connection within the delay')),
      timeout,
    );
    socket.once('secureConnect', onSecure);
    socket.on('error', (err) => finish(networkError(err, false)));
  });
}

/** The fingerprint of the certificate the hub shows (a bare handshake: nothing is sent). */
export function readFingerprint({ host, port, timeout = TIMINGS.connectTimeout, timers }) {
  const t = timers ?? globalThis;
  return new Promise((resolve, reject) => {
    let done = false;
    const socket = tls.connect(options(host, port));
    const finish = (err, value) => {
      if (done) return;
      done = true;
      t.clearTimeout(timer);
      socket.destroy();
      if (err) reject(err);
      else resolve(value);
    };
    const timer = t.setTimeout(
      () => finish(new NeoHubError('timeout', 'no TLS connection within the delay')),
      timeout,
    );
    socket.once('secureConnect', () => {
      const seen = socket.getPeerCertificate()?.fingerprint256;
      if (typeof seen === 'string' && FINGERPRINT.test(seen)) {
        finish(undefined, seen);
      } else {
        finish(new NeoHubError('protocol', 'no certificate shown'));
      }
    });
    socket.on('error', (err) => finish(networkError(err, false)));
  });
}
